var R=prng(72001);
var T0=Date.now();
var N=10;
var adj=[];for(var i=0;i<N;i++)adj.push([]);
function link(a,b,lo,hi){var lat=5+Math.floor(R()*40),cost=1+Math.floor(R()*9),rel=+(lo+R()*(hi-lo)).toFixed(3);adj[a].push({to:b,lat:lat,cost:cost,rel:rel});adj[b].push({to:a,lat:lat,cost:cost,rel:rel});}
for(var i=0;i<N-1;i++)link(i,i+1,0.93,0.99);
var E2=Math.floor(N*0.5);
for(var e=0;e<E2;e++){var a=Math.floor(R()*N),b=Math.floor(R()*N);if(a!==b)link(a,b,0.85,0.999);}
var INF=1e18,dist=new Array(N).fill(INF),vis=new Array(N).fill(false);dist[0]=0;
for(var it=0;it<N;it++){var u=-1,best=INF;for(var i=0;i<N;i++)if(!vis[i]&&dist[i]<best){best=dist[i];u=i;}if(u<0)break;vis[u]=true;adj[u].forEach(function(ed){if(ed.rel>=0.92&&dist[u]+ed.lat<dist[ed.to])dist[ed.to]=dist[u]+ed.lat;});}
console.log(JSON.stringify({id:"JAH-APX72-000001",ok:true,metrics:{nodes:N,path_latency_ms:dist[N-1]===INF?null:dist[N-1],reachable:dist[N-1]!==INF,edges:adj.reduce(function(a,x){return a+x.length;},0)/2,reliability_floor:0.92},ms:Date.now()-T0}));

